matvec_hip_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

#define WARP_SIZE 64
#define BLOCK_SIZE 256

__global__ void matvec_kernel(const float* __restrict__ A, 
                               const float* __restrict__ B, 
                               float* __restrict__ C, 
                               int M, int K) {
    // Each block handles one row of A
    int row = blockIdx.x;
    if (row >= M) return;

    const float* A_row = A + row * K;

    // Each thread processes multiple elements with vectorized loads
    float sum = 0.0f;

    // Use float4 for coalesced memory access
    int vec_K = K / 4;
    const float4* A_row_vec = reinterpret_cast<const float4*>(A_row);
    const float4* B_vec = reinterpret_cast<const float4*>(B);

    for (int i = threadIdx.x; i < vec_K; i += blockDim.x) {
        float4 a_val = A_row_vec[i];
        float4 b_val = B_vec[i];
        sum += a_val.x * b_val.x;
        sum += a_val.y * b_val.y;
        sum += a_val.z * b_val.z;
        sum += a_val.w * b_val.w;
    }

    // Handle remainder
    int remainder_start = vec_K * 4;
    for (int i = remainder_start + threadIdx.x; i < K; i += blockDim.x) {
        sum += A_row[i] * B[i];
    }

    // Warp-level reduction using shuffle
    for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
        sum += __shfl_down(sum, offset);
    }

    // Write partial sums from each warp to shared memory
    __shared__ float warp_sums[BLOCK_SIZE / WARP_SIZE];

    int lane = threadIdx.x % WARP_SIZE;
    int warp_id = threadIdx.x / WARP_SIZE;
    int num_warps = BLOCK_SIZE / WARP_SIZE;

    if (lane == 0) {
        warp_sums[warp_id] = sum;
    }
    __syncthreads();

    // Final reduction by first warp
    if (warp_id == 0) {
        sum = (lane < num_warps) ? warp_sums[lane] : 0.0f;

        for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
            sum += __shfl_down(sum, offset);
        }

        if (lane == 0) {
            C[row] = sum;
        }
    }
}

torch::Tensor matvec_hip(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);

    auto C = torch::zeros({M, 1}, A.options());

    dim3 block(BLOCK_SIZE);
    dim3 grid(M);

    matvec_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K
    );

    return C;
}
