layernorm_cpp_source = """
torch::Tensor layernorm_hip(torch::Tensor input, torch::Tensor gamma, torch::Tensor beta, double eps);
"""

layernorm_hip_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

// Block-level reduction using shared memory for AMD wavefront (64 threads)
__device__ float blockReduceSum(float val, float* shared) {
    int lane = threadIdx.x & 63;  // lane within warp (64-wide wavefront on AMD)
    int wid = threadIdx.x >> 6;   // warp id

    // Warp-level reduction using shuffle
    for (int offset = 32; offset > 0; offset >>= 1) {
        val += __shfl_down(val, offset);
    }

    // Write reduced value of each warp to shared memory
    if (lane == 0) {
        shared[wid] = val;
    }
    __syncthreads();

    // Final reduction in first warp
    int numWarps = (blockDim.x + 63) >> 6;
    val = (threadIdx.x < numWarps) ? shared[threadIdx.x] : 0.0f;

    if (wid == 0) {
        for (int offset = 32; offset > 0; offset >>= 1) {
            val += __shfl_down(val, offset);
        }
    }

    return val;
}

// Optimized LayerNorm kernel - one block per batch element
__global__ void layernorm_kernel(
    const float* __restrict__ input,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ output,
    int batch_size,
    int norm_size,
    float eps
) {
    extern __shared__ float shared[];

    int batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    const float* x = input + batch_idx * norm_size;
    float* y = output + batch_idx * norm_size;

    // Compute mean using parallel reduction
    float local_sum = 0.0f;
    for (int i = threadIdx.x; i < norm_size; i += blockDim.x) {
        local_sum += x[i];
    }

    float mean = blockReduceSum(local_sum, shared);
    __syncthreads();

    // Broadcast mean to all threads
    if (threadIdx.x == 0) {
        shared[0] = mean / norm_size;
    }
    __syncthreads();
    mean = shared[0];

    // Compute variance using parallel reduction
    float local_var = 0.0f;
    for (int i = threadIdx.x; i < norm_size; i += blockDim.x) {
        float diff = x[i] - mean;
        local_var += diff * diff;
    }

    float var = blockReduceSum(local_var, shared);
    __syncthreads();

    // Broadcast variance to all threads
    if (threadIdx.x == 0) {
        shared[0] = var / norm_size;
    }
    __syncthreads();
    var = shared[0];

    float inv_std = rsqrtf(var + eps);

    // Normalize and apply affine transform
    for (int i = threadIdx.x; i < norm_size; i += blockDim.x) {
        float normalized = (x[i] - mean) * inv_std;
        y[i] = normalized * gamma[i] + beta[i];
    }
}

torch::Tensor layernorm_hip(torch::Tensor input, torch::Tensor gamma, torch::Tensor beta, double eps) {
    auto batch_size = input.size(0);
    auto norm_size = input.numel() / batch_size;

    auto output = torch::empty_like(input);

    // Use 1024 threads per block
    const int block_size = 1024;
    const int num_blocks = batch_size;
    const int shared_mem_size = (block_size / 64 + 1) * sizeof(float);  // For warp reduction

    layernorm_kernel<<<num_blocks, block_size, shared_mem_size>>>(
        input.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        norm_size,
        (float)eps
    );

    return output;
}
"""

layernorm_module = load_inline(
    name="layernorm_hip",
    cpp_sources=layernorm_cpp_source,
    cuda_sources=layernorm_hip_source,
    functions=["layernorm_hip"],
    verbose=True,
    extra_cuda_cflags=["-O3", "-ffast-math"]
)


class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = normalized_shape
        self.eps = 1e-5

        # Initialize gamma (weight) and beta (bias) like nn.LayerNorm
        self.gamma = nn.Parameter(torch.ones(normalized_shape))
        self.beta = nn.Parameter(torch.zeros(normalized_shape))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return layernorm_module.layernorm_hip(
            x.contiguous(),
            self.gamma.contiguous().view(-1),
            self.beta.contiguous().view(-1),
            self.eps
        )


