            output.data_ptr<float>(),
            batch_size, channels,
            in_height, in_width,
            out_height, out_width,
            stride, padding
        );
    } else {
        dim3 block(16, 16);
        dim3 grid(
            (out_width + 15) / 16,
            (out_height + 15) / 16,
            batch_size * channels
        );
        depthwise_conv2d_kernel_generic<<<grid, block>>>(
            input.data_ptr<float>(),
            weight.data_ptr<float>(),
            output.data_ptr<float>(),
            batch_size, channels,
            in_height, in_width,
            out_height, out_width,
            kernel_size, stride, padding
        );
    }

