matvec_hip_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

#define WARP_SIZE 64
#define BLOCK_SIZE 1024

__global__ void matvec_kernel_v3(const float* __restrict__ A, 
                                  const float* __restrict__ B, 
                                  float* __restrict__ C, 
                                  int M, int K) {
    // Each block handles one row of A
    int row = blockIdx.x;
    if (row >= M) return;

    const float* A_row = A + (size_t)row * K;

    // Each thread processes multiple elements with vectorized loads
    float sum = 0.0f;

    // Use float4 for coalesced memory access (16 bytes at a time)
    int vec_K = K / 4;
    const float4* A_row_vec = reinterpret_cast<const float4*>(A_row);
    const float4* B_vec = reinterpret_cast<const float4*>(B);

    // Process 4 float4s at a time for better ILP
    int i = threadIdx.x;
    int stride = blockDim.x;

    for (; i < vec_K; i += stride) {
        float4 a_val = A_row_vec[i];
        float4 b_val = B_vec[i];
        sum += a_val.x * b_val.x + a_val.y * b_val.y + a_val.z * b_val.z + a_val.w * b_val.w;
    }

    // Warp-level reduction using shuffle
    #pragma unroll
    for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
        sum += __shfl_down(sum, offset);
    }

    // Write partial sums from each warp to shared memory
    __shared__ float warp_sums[BLOCK_SIZE / WARP_SIZE];

    int lane = threadIdx.x % WARP_SIZE;
    int warp_id = threadIdx.x / WARP_SIZE;
    constexpr int num_warps = BLOCK_SIZE / WARP_SIZE;

    if (lane == 0) {
        warp_sums[warp_id] = sum;
    }
    __syncthreads();

    // Final reduction by first warp
    if (warp_id == 0) {
        sum = (lane < num_warps) ? warp_sums[lane] : 0.0f;

        #pragma unroll
        for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
            sum += __shfl_down(sum, offset);
        }

        if (lane == 0) {
            C[row] = sum;
        }
    }
}

torch::Tensor matvec_hip_v3(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);

    auto C = torch::zeros({M, 1}, A.options());

    dim3 block(BLOCK_SIZE);
    dim3 grid(M);

    matvec_kernel_v3<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K
    );

    return C;
}
